#include <optional>
#include <string_view>

std::optional<int> findFirst(std::string_view text, char target)
{
    for (int i { 0 }; i < static_cast<int>(text.length()); ++i)
    {
        if (text[static_cast<std::size_t>(i)] == target)
            return i;
    }
    return std::nullopt;
}

